mapper.sql:
select case when IQC.TRADE_STATUS = '15' then '03' else '01' end statusValid/*有效*/, '01' quoteType/*交易类型*/, IQC.QUOTE_DATE tradeDate/*成交日期*/, IQC.REPO_PS ps/*本方方向*/, IQC.TRADE_STATUS tradeStatus/*报价状态*/, IQC.SEND_STATUS sendStatus/*发送状态*/, IQC.FPRICE_AMT tradeAmt/*交易金额*/, IQC.RATE rate/*回购利率*/, IQC.TERM repoTerm/*回购期限*/, IQC.QUOTE_ROLE_TYPE quoteRoleType/*本方角色*/, MCCI.PARTY_ABBR ouPartyName/*本方*/, MCCT1.TRADER_NAME ouTraderName /*本方交易员*/, MCP.COUNTER_NAME cpPartyName/*对手方*/, CASE WHEN MCCT.TRADER_NAME is not null THEN MCCT.TRADER_NAME ELSE IQC.CP_TRADER_ID END cpTraderName/*对手方交易员*/, DECODE(IQC.SETTLE_SPEED, 0, '01', 1, '02') settleSpeed/*清算速度*/, IQC.V_SETTLE_DATE vSettleDate/*首次结算日*/, IQC.M_SETTLE_DATE mSettleDate/*到期结算日*/, IQC.QUOTE_ID quoteId/*业务编号*/, TMI.TRD_ID trdId/*成交编号*/, IQC.remark remark/*备注*/, IQC.CREATE_USER, IQC.UPDATE_USER from IBU_QUOTE_CREP IQC LEFT JOIN TRDQUTO_MATCH_INFO TMI ON TMI.PRE_TRADE_ID = IQC.QUOTE_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT ON TFPDT.TOTLE_TRADE_ID = TMI.TRD_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO MCCI ON MCCI.PARTY_ID = IQC.OU_PARTY_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER MCCT ON MCCT.TRADER_ID = IQC.CP_TRADER_ID LEFT JOIN MST_COUNTER_PARTY MCP ON MCP.PARTY_ID = IQC.CP_PARTY_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER MCCT1 ON MCCT1.TRADER_ID = IQC.OU_TRADER_ID where EXISTS ( SELECT 1 FROM IBU_QUOTE_ETR_RE T WHERE T.QUOTE_ID = IQC.QUOTE_ID
AND T.ENTRUST_ID= #{entrustId}
)

select WIQC.WORKFLOW_STATUS statusValid/*有效*/, '01' quoteType/*交易类型*/, WIQC.QUOTE_DATE tradeDate/*成交日期*/, WIQC.REPO_PS ps/*本方方向*/, WIQC.TRADE_STATUS tradeStatus/*报价状态*/, WIQC.SEND_STATUS sendStatus/*发送状态*/, WIQC.FPRICE_AMT tradeAmt/*交易金额*/, WIQC.RATE rate/*回购利率*/, WIQC.TERM repoTerm/*回购期限*/, WIQC.QUOTE_ROLE_TYPE quoteRoleType/*本方角色*/, MCCI.PARTY_ABBR ouPartyName/*本方*/, MCCT1.TRADER_NAME ouTraderName /*本方交易员*/, MCP.COUNTER_NAME cpPartyName/*对手方*/, CASE WHEN MCCT.TRADER_NAME is not null THEN MCCT.TRADER_NAME ELSE WIQC.CP_TRADER_ID END cpTraderName/*对手方交易员*/, DECODE(WIQC.SETTLE_SPEED, 0, '01', 1, '02') settleSpeed/*清算速度*/, WIQC.V_SETTLE_DATE vSettleDate/*首次结算日*/, WIQC.M_SETTLE_DATE mSettleDate/*到期结算日*/, WIQC.QUOTE_ID quoteId/*业务编号*/, TMI.TRD_ID trdId/*成交编号*/, WIQC.remark remark/*备注*/, WIQC.CREATE_USER, WIQC.UPDATE_USER from WFL_IBU_QUOTE_CREP WIQC LEFT JOIN TRDQUTO_MATCH_INFO TMI ON TMI.PRE_TRADE_ID = WIQC.QUOTE_ID LEFT JOIN TRD_FIN_PRODUCT_DEAL_TOTAL TFPDT ON TFPDT.TOTLE_TRADE_ID = TMI.TRD_ID LEFT JOIN MST_CFETS_CUSTOMER_INFO MCCI ON MCCI.PARTY_ID = WIQC.OU_PARTY_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER MCCT ON MCCT.TRADER_ID = WIQC.CP_TRADER_ID LEFT JOIN MST_COUNTER_PARTY MCP ON MCP.PARTY_ID = WIQC.CP_PARTY_ID LEFT JOIN MST_CFETS_CUSTOMER_TRADER MCCT1 ON MCCT1.TRADER_ID = WIQC.OU_TRADER_ID where EXISTS( SELECT 1 FROM IBU_QUOTE_ETR_RE T WHERE T.QUOTE_ID = WIQC.QUOTE_ID
AND T.ENTRUST_ID= #{entrustId}
)

mapper.select:
SELECT * FROM ( SELECT ETR_ENTRUST.ENTRUST_STATUS entrustStatus/*指令状态*/ , (NVL(T5.FINISH_AMT,0)+NVL(T7.ENT_FINISH_AMT,0)) finishAmt/*已完成额度(元)*/ , NVL(ETR_ENTRUST.ENTRUST_AMT, 0) - NVL(T5.FINISH_AMT,0) - NVL(T7.ENT_FINISH_AMT,0) avaNum/*剩余指令额度(元)*/ , ROUND(NVL(C.totalShareAmt,nvl(C2.FPRICE_AMT, 0))+NVL(T6.FINISH_AMT,0)) finishDealAmt/*已成交额度(元)*/ , NVL(ETR_ENTRUST.ENTRUST_AMT, 0) - ROUND(NVL(C.totalShareAmt,nvl(C2.FPRICE_AMT, 0))+NVL(T6.FINISH_AMT,0)) avaDealAmt/*剩余成交额度(元)*/ , trunc(nvl(NVL(T5.FINISH_AMT, 0)+ NVL(T7.ENT_FINISH_AMT, 0),0)/(ETR_ENTRUST.ENTRUST_AMT),4)*100 transactioncom/*执行进度(%)*/ , trunc((NVL(C.totalShareAmt,nvl(C2.FPRICE_AMT, 0))+NVL(T6.FINISH_AMT,0)) /(ETR_ENTRUST.ENTRUST_AMT),4)*100 tradeFinishPercent/* 成交进度(%)*/ , ETR_ENTRUST.ENTRUST_AMT entrustNum/*指令额度(元)*/ , ETR_ENTRUST.PORTFOLIO_ID portfolioId/*组合代码*/ , PTL_PORTFOLIO.PORTFOLIO_NAME portfolioName/*组合名称*/
,PLEDGE.finprodIds /*质押债券*/ ,PLEDGE.finprodMarketNames /*质押债券*/ ,fp.FINPROD_MARKET_ID bondCode ,fp.FINPROD_ABBR bondAbbrName ,PLEDGES.PLEDGE_NUMBER * 100 pledgePrin
,ETR_ENTRUST_ADD.PLEDGE_STOCK_ID pledgeStockId/*质押券库*/ ,ETR_SEC_STOCK.PLEDGE_STOCK_NAME pledgeStockName/*质押券库*/
, ETR_ENTRUST_ADD.SETTLE_SPREED settleSpreed/*清算速度*/ , ETR_ENTRUST.PS ps/*交易方向*/ , ETR_ENTRUST.PRICE_MODEL priceModel/* 价格模式code*/ , ETR_ENTRUST_ADD.TERM_DAYS repoTerm/*回购期限*/ , ETR_ENTRUST.PRICE*100 tradeYield/*回购利率(%)*/ , ETR_ENTRUST.INV_MANAGER_ID invManagerId/*投资经理ID*/ , SU.real_name invManagerName/*投资经理名称*/ , MCP.COUNTER_ID counterId/* 交易对手*/ , MCP.COUNTER_NAME counterName/* 交易对手名称*/ , MCP.PARTY_ID counterPartyId , ETR_ENTRUST.ENTRUST_DATE ENTRUST_DATE/* 指令日期*/ , to_char(ETR_ENTRUST_ADD.TRANSMIT_TIME, 'hh24:mi:ss') TRANSMIT_TIME/* 指令下达时间*/ , ETR_ENTRUST.ENTRUST_ID entrustId/*指令代码*/ , ETR_ENTRUST.REMARK remark/* 备注*/
, ETR_ENTRUST.VDATE vdate/*委托开始日*/ , ETR_ENTRUST.MDATE mdate/*委托结束日*/ , ETR_ENTRUST_ADD.QUOTE_TYPE quoteType/*报价方式*/ , MCCI.PARTY_ID mySide/* 本方 */ , MCCI.PARTY_ABBR mySideAbbr/* 本方名称 */ , ( SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_ID FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN SYS_USER_ADD ON SYS_USER_ADD.ibu_trader = MST_CFETS_CUSTOMER_TRADER.TRADER_ID INNER JOIN SYS_USER ON sys_user.user_name = #{loginUserId} AND sys_user.USER_ID = SYS_USER_ADD.USER_ID WHERE MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = MCCI.PARTY_ID OR MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = ( SELECT MST_CFETS_CUSTOMER_RELA.MPARTY_ID FROM MST_CFETS_CUSTOMER_RELA WHERE MST_CFETS_CUSTOMER_RELA.SPARTY_ID = MCCI.PARTY_ID)) mySideTrader /* 本方交易员 */ , ( SELECT MST_CFETS_CUSTOMER_TRADER.TRADER_NAME FROM MST_CFETS_CUSTOMER_TRADER INNER JOIN SYS_USER_ADD ON SYS_USER_ADD.ibu_trader = MST_CFETS_CUSTOMER_TRADER.TRADER_ID INNER JOIN SYS_USER ON sys_user.user_name = #{loginUserId} AND sys_user.USER_ID = SYS_USER_ADD.USER_ID WHERE MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = MCCI.PARTY_ID OR MST_CFETS_CUSTOMER_TRADER.MPARTY_ID = ( SELECT MST_CFETS_CUSTOMER_RELA.MPARTY_ID FROM MST_CFETS_CUSTOMER_RELA WHERE MST_CFETS_CUSTOMER_RELA.SPARTY_ID = MCCI.PARTY_ID)) mySideTraderName/* 本方交易员名称 */ , ETR_ENTRUST.COUNTER_TRADER counterTrader/* 对手方交易员*/ , MST_CFETS_CT.TRADER_NAME counterTraderName/* 对手方交易员名称*/ , ETR_ENTRUST.CCY settleCcy/* 币种*/ , ETR_ENTRUST.CCY ccy/* 币种*/ , IPAR.CFETS_ACCT_TYPE secAcctSource/* 银行间账户类型，自营/理财*/ , IPAR.PARTY_ID partyId/* 交易成员ID，21位编号*/ , ETR_ENTRUST_ADD.SEC_ACCT_ID secManageAcctId/* 证券账户代码*/ , SECACCT1.ACCT_NO secManageAcctIdZZ/* 中债登 证券账户代码*/ , SECACCT2.ACCT_NO secManageAcctIdSQ/* 上清所 证券账户代码*/ , ETR_ENTRUST_ADD.TERM_TYPE termType /*期限品种*/ , ETR_ENTRUST.TRADE_MARKET/*交易场所，银行间、上交所、深交所、柜面等*/ FROM ETR_ENTRUST INNER JOIN PTL_PORTFOLIO ON ETR_ENTRUST.PORTFOLIO_ID = PTL_PORTFOLIO.PORTFOLIO_ID LEFT JOIN ETR_DISTRIBUTE ON ETR_ENTRUST.ENTRUST_ID = ETR_DISTRIBUTE.ENTRUST_ID LEFT JOIN ETR_ENTRUST_ADD ON ETR_ENTRUST.ENTRUST_ID = ETR_ENTRUST_ADD.ENTRUST_ID LEFT JOIN ( select PORTFOLIO_ID,ACCT_NO from PTL_SEC_ACCT psa inner join STL_SEC_ACCT_INFO ssai on psa.ACCT_NO = ssai.SEC_ACCT_ID and ssai.REGIST_ORG in ('01') and NVL(ssai.sec_acct_type, 'SEC') = 'SEC' and TRADE_PLACE = '01' ) SECACCT1 ON ETR_ENTRUST.PORTFOLIO_ID = SECACCT1.PORTFOLIO_ID LEFT JOIN ( select PORTFOLIO_ID,ACCT_NO from PTL_SEC_ACCT psa inner join STL_SEC_ACCT_INFO ssai on psa.ACCT_NO = ssai.SEC_ACCT_ID and ssai.REGIST_ORG in ('02') and NVL(ssai.sec_acct_type, 'SEC') = 'SEC' and TRADE_PLACE = '01' ) SECACCT2 ON ETR_ENTRUST.PORTFOLIO_ID = SECACCT2.PORTFOLIO_ID LEFT JOIN ( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_QUOTE_FINISH_STATUS GROUP BY ENTRUST_ID) T5 ON ETR_ENTRUST.ENTRUST_ID = T5.ENTRUST_ID LEFT JOIN( SELECT ENTRUST_ID, SUM(FINISH_AMT) AS FINISH_AMT FROM ETR_FINISH_STATUS
INNER JOIN (SELECT DISTINCT T3.TRADE_ID FROM TRDQUTO_MATCH_INFO T1 INNER JOIN REG_FIN_PRODUCT_DEAL_TOTAL T2 ON T1.PRE_TRADE_ID = T2.TOTLE_TRADE_ID INNER JOIN TRD_PRODUCT_DEAL T3 ON T3.TOTLE_TRADE_ID = T1.TRD_ID WHERE TRD_CONF_STATUS = '1') REG ON REG.TRADE_ID = ETR_FINISH_STATUS.TRADE_ID GROUP BY ENTRUST_ID) T6 ON ETR_ENTRUST.ENTRUST_ID = T6.ENTRUST_ID LEFT JOIN( SELECT ENTRUST_ID, SUM(ENT_FINISH_AMT) AS ENT_FINISH_AMT FROM ETR_FINISH_STATUS GROUP BY ENTRUST_ID) T7 ON ETR_ENTRUST.ENTRUST_ID = T7.ENTRUST_ID LEFT JOIN IBU_PORTFOLIO_ACCT_RELA IPAR ON ETR_ENTRUST.PORTFOLIO_ID = IPAR.PORTFOLIO_ID AND IPAR.CFETS_ACCT_TYPE = '01' LEFT JOIN MST_CFETS_CUSTOMER_INFO MCCI ON IPAR.PARTY_ID = MCCI.PARTY_ID LEFT JOIN SYS_USER SU ON ETR_ENTRUST.INV_MANAGER_ID = SU.USER_NAME LEFT JOIN MST_CFETS_CUSTOMER_TRADER MST_CFETS_CT ON MST_CFETS_CT.TRADER_ID = ETR_ENTRUST.COUNTER_TRADER LEFT JOIN MST_COUNTER_PARTY MCP ON MCP.COUNTER_ID = ETR_ENTRUST.COUNTER_ID
LEFT JOIN ( select ENTRUST_ID, listagg(fp.FINPROD_ID, ',')within group(order by ENTRUST_ID) AS finprodIds, listagg(fp.FINPROD_ABBR, ',')within group(order by ENTRUST_ID) AS finprodMarketNames from ETR_PLEDGE ep left join FIN_PRODUCT fp on ep.FINPROD_ID = fp.FINPROD_ID group by ENTRUST_ID ) PLEDGE /*质押式回购银行间报价 按指令代码汇总 交易份额，债券数量等*/ ON PLEDGE.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN ETR_PLEDGE PLEDGES on PLEDGES.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID left join FIN_PRODUCT fp on PLEDGES.FINPROD_ID = fp.FINPROD_ID/*质押式回购银行间报价 按指令代码汇总 交易份额，债券数量等*/
LEFT JOIN ( ) StockFinId on StockFinId.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID
LEFT JOIN ( ) StockFinId on StockFinId.PORTFOLIO_ID = ETR_ENTRUST.PORTFOLIO_ID AND ETR_ENTRUST_ADD.PLEDGE_STOCK_ID = StockFinId.PLEDGE_STOCK_ID LEFT JOIN ETR_SEC_STOCK ON ETR_SEC_STOCK.PLEDGE_STOCK_ID = ETR_ENTRUST_ADD.PLEDGE_STOCK_ID
LEFT JOIN (SELECT iqer.ENTRUST_ID, SUM(nvl(iqer.FPRICE_AMT, 0)) totalShareAmt FROM IBU_QUOTE_ETR_RE iqer /*质押式回购银行间报价*/ where QUOTE_ID in (select QUOTE_ID from IBU_QUOTE_CREP where TRADE_STATUS = '07') GROUP BY iqer.ENTRUST_ID) C /*质押式回购银行间报价 按指令代码汇总 交易份额，债券数量等*/ ON C.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID LEFT JOIN (SELECT iqer.ENTRUST_ID, iqer.FPRICE_AMT FROM IBU_QUOTE_ETR_RE iqer /*质押式回购银行间报价*/ where QUOTE_ID in (select QUOTE_ID from IBU_QUOTE_CREP where TRADE_STATUS = '07')) C2/*质押式回购银行间报价*/ ON C2.ENTRUST_ID = ETR_ENTRUST.ENTRUST_ID WHERE ETR_ENTRUST.FINPROD_TYPE2 in (#{finprodType2_F02},#{finprodType2_F03}) AND ETR_ENTRUST.TRADE_MARKET IN (#{tradeMarket01} , #{tradeMarket02}) AND ETR_ENTRUST.PS IN (#{ps_03} , #{ps_04} ) AND ETR_ENTRUST.ENTRUST_STATUS IN (#{entrustStatusUnAccept}, #{entrustStatusAccept}, #{entrustStatusComple}, #{entrustStatusReturn})
/* 查询条件 报价编号（内部代码）*/ AND StockFinId.FINPROD_ID in (select iqcp.PLEDGE_FINPROD_ID from IBU_QUOTE_CREP_PLEDGE iqcp left join IBU_QUOTE_CREP iqc on iqcp.QUOTE_ID = iqc.QUOTE_ID and iqcp.VERSION = iqc.VERSION where iqc.TRADE_STATUS = '09' and iqc.QUOTE_ID = #{quoteId})
/* 查询条件 报价编号（内部代码）*/ AND fp.FINPROD_ID in (select iqcp.PLEDGE_FINPROD_ID from IBU_QUOTE_CREP_PLEDGE iqcp left join IBU_QUOTE_CREP iqc on iqcp.QUOTE_ID = iqc.QUOTE_ID and iqcp.VERSION = iqc.VERSION where iqc.TRADE_STATUS = '09' and iqc.QUOTE_ID = #{quoteId})
/* 查询条件 指令状态*/ AND ETR_ENTRUST.ENTRUST_STATUS IN
#{item}
/* 已接收未完成的当日质押式回购指令供选择*/ AND ETR_ENTRUST.ENTRUST_DATE = to_date(#{platDate}, 'yyyy-MM-dd')
/* 查询条件 价格模式*/ AND ETR_ENTRUST.PRICE_MODEL IN
#{item}
/* 查询条件 投资经理*/ AND ETR_ENTRUST.INV_MANAGER_ID IN
#{item}
AND IPAR.PARTY_ID = #{mySide}
/* 查询条件 交易员*/ AND ETR_DISTRIBUTE.TRADER = #{loginUserId}
/* 查询条件 质押券库*/ AND ETR_ENTRUST.PLEDGE_STOCK_ID IN
#{item}
and ETR_ENTRUST.ENTRUST_ID in
#{item}
and ETR_ENTRUST.ENTRUST_ID not in
#{item}
and ( ETR_ENTRUST.COUNTER_ID in ( select COUNTER_ID from ETR_ENTRUST where ENTRUST_ID in
#{item}
) or ETR_ENTRUST.COUNTER_ID is null )
order by decode(ETR_ENTRUST.ENTRUST_STATUS,'09',1,'02',2,'03',3,'04',4,'06',5,'05',6,'07',7),ETR_ENTRUST_ADD.TRANSMIT_TIME,ETR_ENTRUST.ps)
